  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="support-card" aria-labelledby="support-title">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">How can we reach you?</h1>
        <p class="intro">
          Share your contact details and our support team will use them to follow
          up about your request.
        </p>

        <form id="support-form" novalidate>
          <p class="required-note">
            Fields marked with <span class="required-marker" aria-hidden="true">*</span>
            are required.
          </p>

          <div class="form-field">
            <label for="full-name">
              Full name <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
            >
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span class="required-marker" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              required
            >
          </div>

          <div class="form-field">
            <label for="phone">Phone number (optional)</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help"
            >
            <p id="phone-help" class="helper-text">
              Include country and area codes when needed, for example +1 555 123
              4567.
            </p>
          </div>

          <div class="actions">
            <button type="submit">Send request</button>
          </div>

          <p id="form-status" class="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#support-form");
      const status = document.querySelector("#form-status");
      const requiredFields = [
        {
          input: document.querySelector("#full-name"),
          message: "Error: Enter your full name."
        },
        {
          input: document.querySelector("#email"),
          message: "Error: Enter a valid email address, like name@example.com."
        }
      ];

      function getDescribedBy(input) {
        return input.getAttribute("aria-describedby")
          ?.split(/\s+/)
          .filter(Boolean) ?? [];
      }

      function setError(input, message) {
        const errorId = `${input.id}-error`;
        let error = document.querySelector(`#${errorId}`);

        if (!error) {
          error = document.createElement("p");
          error.id = errorId;
          error.className = "error-message";
          input.insertAdjacentElement("afterend", error);
        }

        error.textContent = message;
        input.setAttribute("aria-invalid", "true");

        const describedBy = new Set([...getDescribedBy(input), errorId]);
        input.setAttribute("aria-describedby", [...describedBy].join(" "));
      }

      function clearError(input) {
        const errorId = `${input.id}-error`;
        const error = document.querySelector(`#${errorId}`);
        const describedBy = getDescribedBy(input).filter((id) => id !== errorId);

        error?.remove();
        input.removeAttribute("aria-invalid");

        if (describedBy.length > 0) {
          input.setAttribute("aria-describedby", describedBy.join(" "));
        } else {
          input.removeAttribute("aria-describedby");
        }
      }

      function validateField(input, message) {
        if (input.validity.valid) {
          clearError(input);
          return true;
        }

        setError(input, message);
        return false;
      }

      requiredFields.forEach(({ input, message }) => {
        input.addEventListener("input", () => {
          if (input.getAttribute("aria-invalid") === "true") {
            validateField(input, message);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        const invalidFields = requiredFields.filter(
          ({ input, message }) => !validateField(input, message)
        );
        const firstInvalid = invalidFields[0];

        if (firstInvalid) {
          firstInvalid.input.focus();
          return;
        }

        form.reset();
        requiredFields.forEach(({ input }) => clearError(input));
        status.textContent = "Thanks. Your support request contact details were sent.";
      });
    </script>
  </body>
