        transform: translateY(0);
        outline: 3px solid var(--primary);
        outline-offset: 3px;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem;
      }

      .support-card {
        width: min(100%, 42rem);
        border: 1px solid rgba(203, 213, 225, 0.85);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 3rem);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3.25rem);
        line-height: 1.05;
        letter-spacing: -0.045em;
      }

      .intro {
        margin: 1rem 0 2rem;
        max-width: 34rem;
        color: var(--muted);
        font-size: 1.0625rem;
        line-height: 1.65;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .required-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.9375rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-weight: 750;
